import time

cache = {}   # key -> (value, expires_at)

def get(key):
    hit = cache.get(key)
    if hit and hit[1] > time.time():
        return hit[0]              # still fresh
    cache.pop(key, None)          # expired -> evict
    return None

def put(key, value, ttl_s=300):
    cache[key] = (value, time.time() + ttl_s)

def invalidate(prefix):
    # drop everything affected by an underlying data change
    for k in [k for k in cache if k.startswith(prefix)]:
        cache.pop(k, None)

