    return hashlib.sha256(blob.encode()).hexdigest()

def cached_generate(prompt, **params):
    k = key(prompt, params)
    if k in cache:
        return cache[k]                 # no model call
    resp = model_generate(prompt, **params)
    cache[k] = resp
    return resp

